    Lemma bpushd_fin : forall msF mo mc (r : rv) Fx fcx j16 mw bw ew xg j6 f0 (p' : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xfff88) fcx None mc (seg_rom asegs) -> frm0 fcx ->
