    Lemma ufi_fin : forall (pc0 : Z) (payf : bvmap 5 word -> word -> word) msF mo mc m1 (sx : as_St H) (r : rv) Fx fcx j16 mw bw ew xg j6 f0 (p' : Z) (pw : word)
        (pb : bptr) (Bb cap : Z) (errv1 : word),
      let st1 := mkVS (Some (pb, Bb, 24 * cap)) cap (vs_items (ps_vs ps0)) 0 (vs_temp (ps_vs ps0)) in
      uf_seg 2 pc0 0x100098 (fun rq w => rs4 rq = w) payf (fun _ w => w) ->
      as_AKREL H sx (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H sx msF = MS (mkRr r) Fx (Z_to_bv 64 pc0) fcx None m1 (seg_rom asegs) -> frm0 fcx ->
      nst mc -> xpres H REST (bv_unsigned spw) (vs_X pa) mc m1 ->
      as_RHEAP H sx (blocks_vs st1 ++ REST) m1 -> vs_at m1 pa st1 ->
      mem_inv asegs m1 -> as_rauxv_ok H m1 B -> rw_cells asegs m1 (errno_addr tp) [C4 errv1] -> bj_statics m1 -> ACONST m1 ->
      as_RFS H LF m1 -> addressable m1 pa 280 -> stack0 m1 lo (bv_unsigned sp) -> stk asegs m1 lo (bv_unsigned spw) ->
      nframe m1 spw j16 mw bw ew xg (b8 1) j6 f0 s6 s5 s4 s3 s2 s1 s0 ra ->
      rsp r = spw -> rgp r = gp -> rtp r = tp -> rs0 r = a0 -> rs1 r = Z_to_bv 64 p' ->
      rs2 r = Z_to_bv 64 (pa + 24) -> rs3 r = Z_to_bv 64 (sh8 (pa + 24)) -> rs5 r = Z_to_bv 64 2147450880 -> rs4 r = pw ->
      rs7 r = s7 -> rs8 r = s8 -> rs9 r = s9 -> rs10 r = s10 -> rs11 r = s11 ->
      vs_n st1 < cap ->
      (cap = vs_cap (ps_vs ps0) \/ (vs_n (ps_vs ps0) = vs_cap (ps_vs ps0) /\ cap = grow_cap (vs_cap (ps_vs ps0)))) ->
      as_AL H sx >= as_AL H s - push_cost H (ps_vs ps0) ->
      p < p' <= e ->
      as_SR H POST (mkCfg msF mo).
Proof.
