    (* [comment removed for export] *)
    Ltac xlh_next msF1 mo1 r1 Fx j6 f0 IH q1 :=
      lazymatch goal with E1 : as_VIS _ _ msF1 = MS _ _ _ _ _ _ _ |- _ =>
        let FRx := fresh "FRx" in leaf_frame FRx;
        lazymatch type of FRx with
        | nframe _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ =>
            eapply (xls_loop q1 msF1 mo1 _ r1 Fx);
              [eassumption| mp_tac| exact E1| eassumption| eassumption| eassumption| eassumption| exact FRx| bregs_tac| first [breg1 | lia] ..]
        | _ =>
            eapply (IH q1 msF1 mo1 _ r1 Fx);
              [lia| eassumption| mp_tac| exact E1| eassumption| eassumption| eassumption| eassumption| exact FRx| bregs_tac| first [breg1 | lia] ..]
        end
      end.
    (* [comment removed for export] *)
    Lemma xlh_loop_n : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx j16 (mw : word) (bc xc xn : Z) j6 f0,
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xffac0) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j16 mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 1) j6 f0 s6 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra7 r = Z_to_bv 64 xc -> ra1 r = Z_to_bv 64 9 -> ra2 r = Z_to_bv 64 (- 2147483649) -> ra3 r = Z_to_bv 64 214748364 -> ra4 r = Z_to_bv 64 2 -> ra5 r = Z_to_bv 64 55 -> ra6 r = Z_to_bv 64 10 ->
      p + 2 <= q < e -> -67108864 < bc < 67108864 -> 0 <= xc <= 2147483647 -> 0 <= xn <= 1 ->
