    (* [comment removed for export] *)
    Lemma skh_loop_n : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx j16 (mw : word) (bc : Z) j6 f0,
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xff67c) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j16 mw (Z_to_bv 64 bc) (Z_to_bv 64 0) (b8 0) (b8 1) j6 f0 s6 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 9 -> ra2 r = Z_to_bv 64 2 ->
      p + 2 <= q < e -> -67108864 < bc < 67108864 ->
