    Lemma bigl_loop : forall (i : Z) msF mo mc (r : rv) Fx j16 (mw bw : word) (b bc : Z) j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xff5c0) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j16 mw bw (Z_to_bv 64 0) (b8 0) (b8 1) j6 f0 s6 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> ra0 r = Z_to_bv 64 b -> ra2 r = Z_to_bv 64 i -> ra4 r = Z_to_bv 64 bc -> ra6 r = Z_to_bv 64 bc -> ra5 r = Z_to_bv 64 9 -> ra7 r = Z_to_bv 64 2147483647 -> rt0 r = Z_to_bv 64 2 ->
      p + 2 <= b -> 0 <= i -> b + i + 1 < e -> 1 <= bc <= i + 1 ->
      as_SR H POST (mkCfg msF mo).
Proof.
