    Lemma slow_fin : forall msF mo mc (r : rv) Fx j16 (mant : word) j6 f0,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xff4bc) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j16 mant (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 f0 s6 s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs3 r = Z_to_bv 64 p -> rs1 r = Z_to_bv 64 (p + 1) ->
      e <= p + 33 ->
      as_SR H POST (mkCfg msF mo).
